<script setup lang="ts">
definePageMeta({middleware:['auth','repairer']})
const supabase=useSupabaseClient(); const {company,profile,loadProfile}=useProfile(); const stats=reactive({open:0,offers:0,fulfilled:0}); const loading=ref(true)
onMounted(async()=>{await loadProfile(); if(!isValidUuid(company.value?.id)){loading.value=false;return} const [req,fulfilled]=await Promise.all([supabase.from('wanted_requests').select('id',{count:'exact'}).eq('repairer_company_id',company.value.id).eq('status','open'),supabase.from('wanted_requests').select('id',{count:'exact',head:true}).eq('repairer_company_id',company.value.id).eq('status','fulfilled')]); stats.open=req.count||0;stats.fulfilled=fulfilled.count||0; const ids=(req.data||[]).map((r:any)=>r.id).filter(isValidUuid); if(ids.length){const o=await supabase.from('wanted_offers').select('*',{count:'exact',head:true}).in('request_id',ids).eq('status','pending');stats.offers=o.count||0} loading.value=false})
</script>
<template><section class="section"><div class="container"><div class="kicker">Repairer portal</div><h1 class="page-title" style="margin-top:8px">Repairer Dashboard</h1><p class="muted" v-if="company">{{company.name}} · {{profile?.full_name}}</p><div class="grid grid-3" style="margin-top:24px"><div class="card stat"><strong>{{loading?'—':stats.open}}</strong><span class="muted">Open wanted requests</span></div><div class="card stat"><strong>{{loading?'—':stats.offers}}</strong><span class="muted">Pending supplier offers</span></div><div class="card stat"><strong>{{loading?'—':stats.fulfilled}}</strong><span class="muted">Fulfilled requests</span></div></div><div class="grid grid-3" style="margin-top:22px"><div class="card" style="padding:22px"><h2>Find a Part</h2><p class="muted">Search supplier inventory by vehicle, part number and location.</p><NuxtLink class="btn btn-primary" to="/search">Search Marketplace</NuxtLink></div><div class="card" style="padding:22px"><h2>Wanted Parts</h2><p class="muted">Manage requests and compare supplier offers.</p><NuxtLink class="btn btn-secondary" to="/repairer/wanted">My Wanted Requests</NuxtLink></div><div class="card" style="padding:22px"><h2>Can't find it?</h2><p class="muted">Publish a request and let suppliers come to you.</p><NuxtLink class="btn btn-secondary" to="/repairer/wanted/new">Create Wanted Request</NuxtLink></div></div></div></section></template>
